import{_ as a,c as r,o as t,a4 as o}from"./chunks/framework.BU14wsQo.js";const n="/ai/daily/2026-06-30/news_01kwbat4tme8hsx4t94cbenqpt.avif",l="/ai/daily/2026-06-30/news_01kwbaxccge8hsx4w85y3z3fdx.mp4",i="/ai/daily/2026-06-30/news_01kwbat7x3e8hsx4tj0w11a8sc.avif",s="/ai/daily/2026-06-30/news_01kwbb058me8hsx4wjewggyqhr.mp4",h="/ai/daily/2026-06-30/news_01kwbatewve8hsx4trcqpczf1p.avif",k=JSON.parse('{"title":"AI大事件 2026/6/30","description":"AI大事件 2026/6/30 - 陈老板的百宝箱 AI 大事件日报，追踪模型发布、AI 产品、前沿研究、开源工具、安全政策与行业动态。","frontmatter":{"linkTitle":"06-30 AI大事件","title":"AI大事件 2026/6/30","weight":2,"breadcrumbs":false,"comments":true,"description":""},"headers":[],"relativePath":"ai/daily/cn/2026-06/2026-06-30.md","filePath":"AI/daily/cn/2026-06/2026-06-30.md","lastUpdated":1783497398000}'),d={name:"ai/daily/cn/2026-06/2026-06-30.md"};function c(p,e,u,m,b,f){return t(),r("div",null,[...e[0]||(e[0]=[o(`<h1 align="center">2026-06-30 AI大事件</h1><h2 id="今日摘要" tabindex="-1"><strong>今日摘要</strong> <a class="header-anchor" href="#今日摘要" aria-label="Permalink to &quot;**今日摘要**&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>模型与产品更新：美团发布VitaBench2.0评测系统、Cursor发布移动端编码程序、苹果紧急推送iOS系统安全更新 🚀</span></span>
<span class="line"><span>前沿研究：智谱GLM5.2模型比肩Claude、学者利用AI攻克计算几何难题、研究人员提出AgentOdyssey框架 🧠</span></span>
<span class="line"><span>行业、政策与安全：Tidal平台出台AI音乐新政策、北京太空算力创新中心揭牌、DeepSeek创始人决定启动融资 🔒</span></span>
<span class="line"><span>开源与开发者工具：VeraCrypt: 强大磁盘加密工具、tolaria: 桌面端知识库管理、VulnClaw: 自动化安全渗透框架 🛠️</span></span>
<span class="line"><span>社媒与观点：独立开发者分享价值开源项目、圈内热议DeepSeek价格上涨、Qwen 3.6 27B 是本地开发的理想选择 ( •̀ ω •́ )</span></span>
<span class="line"><span>今天的主线是模型、工具、研究与产业部署继续向可执行工作流收敛 (๑•̀ㅂ•́)و✧</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="模型与产品更新" tabindex="-1">模型与产品更新 <a class="header-anchor" href="#模型与产品更新" aria-label="Permalink to &quot;模型与产品更新&quot;">​</a></h2><h3 id="_1-美团发布-vitabench2-0-评测系统" tabindex="-1">1. 美团发布 VitaBench2.0 评测系统 <a class="header-anchor" href="#_1-美团发布-vitabench2-0-评测系统" aria-label="Permalink to &quot;1. 美团发布 VitaBench2.0 评测系统&quot;">​</a></h3><p>美团发布 VitaBench2.0 评测系统 美团团队发布 VitaBench2.0 基准。它是 🚀 首个针对动态用户建模的 智能体系统（AI 资讯）。系统涵盖 56 位用户与海量任务。测试发现大模型(T_T)缺乏主动沟通意愿。该项目开源将推动 AI 向伴侣进化。 来源：<a href="https://tech.meituan.com/2026/06/29/LongCat-VitaBench-2.0.html" target="_blank" rel="noreferrer">智能体系统（AI 资讯）</a></p><p><img src="`+n+'" alt="AI资讯：美团团队展示VitaBench评测基准概览图" loading="lazy"></p><h3 id="_2-cursor-发布移动端编码程序" tabindex="-1">2. Cursor 发布移动端编码程序 <a class="header-anchor" href="#_2-cursor-发布移动端编码程序" aria-label="Permalink to &quot;2. Cursor 发布移动端编码程序&quot;">​</a></h3><p>Cursor 发布移动端编码程序 Cursor 正式推出 移动端编码程序。开发者可通过手机启动 远程代理（AI 资讯）。此举呼应了服务全面转向的 🚀 战略。移动端编码正迅速演变为(✧∀✧)新常态。未来软件工程协作景观将被重塑。 来源：<a href="https://www.aibase.com/zh/news/29244" target="_blank" rel="noreferrer">远程代理（AI 资讯）</a></p><h3 id="_3-苹果紧急推送-ios-系统安全更新" tabindex="-1">3. 苹果紧急推送 iOS 系统安全更新 <a class="header-anchor" href="#_3-苹果紧急推送-ios-系统安全更新" aria-label="Permalink to &quot;3. 苹果紧急推送 iOS 系统安全更新&quot;">​</a></h3><p>苹果紧急推送 iOS 系统安全更新 苹果公司紧急推送 iOS 系统安全更新。此举旨在应对不断上升的 黑客风险（AI 资讯）。AI 爆发导致恶意工具开发 🔥 大幅加快。苹果正联合 Anthropic(O_O)发现漏洞。加快更新节奏正成为安全新常态。 来源：<a href="https://www.aibase.com/zh/news/29242" target="_blank" rel="noreferrer">黑客风险（AI 资讯）</a></p><h3 id="_4-英伟达重磅发布-bionemo-工具包" tabindex="-1">4. 英伟达重磅发布 BioNeMo 工具包 <a class="header-anchor" href="#_4-英伟达重磅发布-bionemo-工具包" aria-label="Permalink to &quot;4. 英伟达重磅发布 BioNeMo 工具包&quot;">​</a></h3><p>英伟达重磅发布 BioNeMo 工具包 英伟达重磅发布 BioNeMo 工具包。工具将分子模型转化为 🚀 可调用 专属技能（AI 资讯）。智能体任务完成率(✧∀✧)瞬间飙升至满分。代理有效断言平均增加了近两倍。此举为药物发现领域带来全新可能。 来源：<a href="https://www.marktechpost.com/2026/06/29/nvidia-bionemo-agent-toolkit-turns-biomolecular-models-into-callable-skills-for-ai-agents-in-drug-discovery/" target="_blank" rel="noreferrer">专属技能（AI 资讯）</a></p><h3 id="_5-从任何地点构建——cursor-for-ios-公测版发布" tabindex="-1">5. 从任何地点构建——Cursor for iOS 公测版发布 <a class="header-anchor" href="#_5-从任何地点构建——cursor-for-ios-公测版发布" aria-label="Permalink to &quot;5. 从任何地点构建——Cursor for iOS 公测版发布&quot;">​</a></h3><p>Cursor 推出 iOS 原生公测版，所有付费计划可用。开发者可在手机上启动始终在线的云端智能体，或远程操控电脑端智能体。支持语音输入、斜杠命令和选择前沿模型。智能体运行后，锁屏 Live Activities 和推送通知实时更新状态，完成或需要输入时提醒。云端智能体在隔离虚拟机中运行，可自动迭代生成合并就绪的 PR，并输出演示、截图和日志。本地与云端智能体支持双向切换。移动端 Composer 2.5 享受 75% 折扣，优惠至 2026 年 7 月 5 日。 来源：<a href="https://cursor.com/blog/ios-mobile-app" target="_blank" rel="noreferrer">Cursor Blog</a></p><h3 id="_6-everos-开源-markdown-优先智能体记忆运行时-支持混合检索与自进化技能" tabindex="-1">6. EverOS：开源 Markdown 优先智能体记忆运行时，支持混合检索与自进化技能 <a class="header-anchor" href="#_6-everos-开源-markdown-优先智能体记忆运行时-支持混合检索与自进化技能" aria-label="Permalink to &quot;6. EverOS：开源 Markdown 优先智能体记忆运行时，支持混合检索与自进化技能&quot;">​</a></h3><p>EverMind 推出开源智能体记忆运行时 EverOS（Apache 2.0 许可）。它以可编辑的 Markdown 文件为记忆主体，经 SQLite 管理状态、LanceDB 实现混合检索（BM25 关键词 + 向量搜索 + 标量过滤）。每个完成的任务记录为 Case，离线提炼为可复用的 Skill，使记忆随使用自我进化。v1.1.0 新增 Knowledge APIs（支持分类与话题搜索的 Markdown 页面）和 Reflection（跨会话优化 Profile 和 Skill）。据 EverMind 报告，LoCoMo 得分 93.05%，LongMemEval 83.00%，HaluMem 93.04%，p95 检索延… 来源：<a href="https://www.marktechpost.com/2026/06/29/meet-everos-an-open-source-markdown-first-agent-memory-runtime-with-hybrid-bm25-vector-retrieval-and-self-evolving-skills" target="_blank" rel="noreferrer">MarkTechPost（RSS）</a></p><h3 id="_7-小红书-redknot-推理引擎-将-kv-cache-按注意力头拆解实现长文本加速" tabindex="-1">7. 小红书 RedKnot 推理引擎：将 KV Cache 按注意力头拆解实现长文本加速 <a class="header-anchor" href="#_7-小红书-redknot-推理引擎-将-kv-cache-按注意力头拆解实现长文本加速" aria-label="Permalink to &quot;7. 小红书 RedKnot 推理引擎：将 KV Cache 按注意力头拆解实现长文本加速&quot;">​</a></h3><p>RedKnot 将 KV Cache 沿注意力头维度拆解，通过头分类稀疏（局部头占 83.4%–96.8%）、稀疏 FFN 和 SegPagedAttention 三个机制统一算法与存储粒度。在 8 卡 H800 上，TTFT 最高加速 1.6–3.54×，单卡并发提升 4.7–7.8×，预填充 FLOPs 削减 67%–79.5%。DeepSeek-V4-Flash 上 128K 上下文 TTFT 加速达 5.16×，KV 传输最多省 6.3×。精度通常不低于稠密 F1 的 95%。 来源：<a href="https://mp.weixin.qq.com/s/qRrZvL0aZzYI82djFSrLug" target="_blank" rel="noreferrer">公众号：小红书技术（dots.llm）</a></p><h3 id="_8-herdr-驻留在终端中的-ai-智能体多路复用器" tabindex="-1">8. Herdr：驻留在终端中的 AI 智能体多路复用器 <a class="header-anchor" href="#_8-herdr-驻留在终端中的-ai-智能体多路复用器" aria-label="Permalink to &quot;8. Herdr：驻留在终端中的 AI 智能体多路复用器&quot;">​</a></h3><p>Herdr 是一个驻留在终端中的 AI 智能体多路复用器，允许用户在单一终端界面内管理和切换多个 AI 智能体会话。 来源：<a href="https://github.com/ogulcancelik/herdr" target="_blank" rel="noreferrer">Hacker News 热门（buzzing.cc 中文翻译）</a></p><h3 id="_9-为-amazon-bedrock-和-google-cloud-推出的-claude-apps-gateway" tabindex="-1">9. 为 Amazon Bedrock 和 Google Cloud 推出的 Claude apps gateway <a class="header-anchor" href="#_9-为-amazon-bedrock-和-google-cloud-推出的-claude-apps-gateway" aria-label="Permalink to &quot;9. 为 Amazon Bedrock 和 Google Cloud 推出的 Claude apps gateway&quot;">​</a></h3><p>Anthropic 今日推出 Claude apps gateway，一个自托管控制平面，让企业能在 Amazon Bedrock 和 Google Cloud 上运行 Claude Code。它作为单个无状态容器部署于 Linux，后端使用 PostgreSQL，提供企业级 SSO 登录（通过 OIDC 对接 Google Workspace、Microsoft Entra ID、Okta 等）、集中策略管理、角色权限、路由（支持故障转移）以及按日/周/月、按组织/群组/用户的消费上限。遥测数据通过 OTLP 发送至用户配置的收集器。gateway 不会向 Anthropic 发送推理流量或使用数据（除非配置使用 Claude A… 来源：<a href="https://claude.com/blog/introducing-the-claude-apps-gateway" target="_blank" rel="noreferrer">Claude：Blog（网页）</a></p><h3 id="_10-claude-在-microsoft-foundry-正式可用" tabindex="-1">10. Claude 在 Microsoft Foundry 正式可用 <a class="header-anchor" href="#_10-claude-在-microsoft-foundry-正式可用" aria-label="Permalink to &quot;10. Claude 在 Microsoft Foundry 正式可用&quot;">​</a></h3><p>从今天起，Claude 模型在 Microsoft Foundry 上正式可用，托管于 Azure 环境，运行在 NVIDIA GB300 GPU 上。首批提供 Claude Opus 4.8 和 Claude Haiku 4.5，通过 Messages API 调用，支持提示缓存和扩展思考。用户可选择推理处理位置，包括美国数据区域，由 Anthropic 负责推理运营。Azure 用户可使用现有身份验证、计费与治理控制，并获得统一账单；符合条件的 Enterprise Agreement 客户可将 Claude 用量计入 Azure 承诺消费。 来源：<a href="https://claude.com/blog/claude-in-microsoft-foundry" target="_blank" rel="noreferrer">Claude：Blog（网页）</a></p><h3 id="_11-claude-code-v2-1-196-发布" tabindex="-1">11. Claude Code v2.1.196 发布 <a class="header-anchor" href="#_11-claude-code-v2-1-196-发布" aria-label="Permalink to &quot;11. Claude Code v2.1.196 发布&quot;">​</a></h3><p>新增组织默认模型支持，未选模型时显示“Org default”。聊天会话可读默认名称，文件附件支持 Cmd/Ctrl-click 定位。安全方面，<code>claude mcp list/get</code> 不再启动通过 <code>.claude/settings.json</code> 自批准的不安全服务器；不受信任工作区显示“Pending approval”。<code>/code-review</code> 合并五个清理查找器，token 用量减少约 25%。终端 UI 跳过空子树遍历减少渲染。流式空闲看门狗默认开启，5 分钟无事件自动中止重试。修复背景对话误删、远程会话自动恢复、MCP OAuth 作用域冲突、Agents 侧边栏焦点丢失等多项问题。 来源：<a href="https://github.com/anthropics/claude-code/releases/tag/v2.1.196" target="_blank" rel="noreferrer">Claude Code：GitHub Releases（RSS）</a></p><h2 id="前沿研究" tabindex="-1">前沿研究 <a class="header-anchor" href="#前沿研究" aria-label="Permalink to &quot;前沿研究&quot;">​</a></h2><h3 id="_1-智谱-glm5-2-模型比肩-claude" tabindex="-1">1. 智谱 GLM5.2 模型比肩 Claude <a class="header-anchor" href="#_1-智谱-glm5-2-模型比肩-claude" aria-label="Permalink to &quot;1. 智谱 GLM5.2 模型比肩 Claude&quot;">​</a></h3><p>智谱 GLM5.2 模型比肩 Claude 智谱开放权重的 GLM5.2 模型 表现抢眼。它在安全任务中比肩 受限模型（AI 资讯）。这证明国产大模型在漏洞检测上 🚀 极强。该进展加剧了对(✧∀✧)出口管制策略探讨。开源生态正重塑全球 AI 安全技术格局。 来源：<a href="http://mp.weixin.qq.com/s?__biz=MjM5NjA0NjgyMA==&amp;mid=2651341457&amp;idx=1&amp;sn=6cb6f18e45073e2a0112b42f3c8fbde2&amp;chksm=bc1c110f3f5c5bf132774ce07fceb76800bfafaaf15044f1050345ede904aaef332d6970c8d8&amp;scene=0&amp;xtrack=1#rd" target="_blank" rel="noreferrer">受限模型（AI 资讯）</a></p><h3 id="_2-学者利用-ai-攻克计算几何难题" tabindex="-1">2. 学者利用 AI 攻克计算几何难题 <a class="header-anchor" href="#_2-学者利用-ai-攻克计算几何难题" aria-label="Permalink to &quot;2. 学者利用 AI 攻克计算几何难题&quot;">​</a></h3><p>学者利用 AI 攻克计算几何难题 加州大学学者利用 AI 攻克 计算几何难题。他们用模型证明了最远点对等 经典数学问题（AI 资讯）。初始证明由 AI 生成并 🚀 实现了关键突破。姚班天才陈立杰此前工作成为(✧∀✧)关键。人机协作正成为系统解决难题的新范式。 来源：<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;mid=2652709773&amp;idx=2&amp;sn=68bde762eb0070f5bd61518728971232" target="_blank" rel="noreferrer">经典数学问题（AI 资讯）</a></p><h3 id="_3-研究人员提出-agentodyssey-框架" tabindex="-1">3. 研究人员提出 AgentOdyssey 框架 <a class="header-anchor" href="#_3-研究人员提出-agentodyssey-框架" aria-label="Permalink to &quot;3. 研究人员提出 AgentOdyssey 框架&quot;">​</a></h3><p>研究人员提出 AgentOdyssey 框架 科研人员提出全新评估框架 AgentOdyssey。系统生成开放文本游戏测试 智能体（AI 资讯）。AI 被置于连续 🚀 环境中交替学习与推理。测试结果揭示了顶级模型(O_O)能力的不足。研究证实短期记忆是测试训练重要部分。 来源：<a href="https://huggingface.co/papers/2606.24893" target="_blank" rel="noreferrer">智能体（AI 资讯）</a></p><p><video controls src="'+l+'" title="AI资讯"></video></p><h3 id="_4-阿里发布-qwenimage2-0rl-报告" tabindex="-1">4. 阿里发布 QwenImage2.0RL 报告 <a class="header-anchor" href="#_4-阿里发布-qwenimage2-0rl-报告" aria-label="Permalink to &quot;4. 阿里发布 QwenImage2.0RL 报告&quot;">​</a></h3><p>阿里发布 QwenImage2.0RL 报告 阿里重磅发布 QwenImage2.0RL 报告。新技术利用强化学习提升了 画面质量（AI 资讯）。策略蒸馏被首次应用于 🚀 扩散模型后训练。模型在指令遵循和编辑上(✧∀✧)极其出色。这一成果对开源文生图生态有示范效应。 来源：<a href="https://huggingface.co/papers/2606.27608" target="_blank" rel="noreferrer">画面质量（AI 资讯）</a></p><p><img src="'+i+'" alt="AI资讯：阿里团队展示通义千问多模态模型论文封面图" loading="lazy"></p><h3 id="_5-英伟达推出仿真训练系统-simfoundry" tabindex="-1">5. 英伟达推出仿真训练系统 SimFoundry <a class="header-anchor" href="#_5-英伟达推出仿真训练系统-simfoundry" aria-label="Permalink to &quot;5. 英伟达推出仿真训练系统 SimFoundry&quot;">​</a></h3><p>英伟达推出仿真训练系统 SimFoundry 英伟达推出全新仿真训练系统 SimFoundry。该技术能根据视频自动构建 三维场景（AI 资讯）。虚拟训练的机器人可以直接 🚀 落地上岗。真实测试显示复杂操作成功率(o ﾟ ▽ ﾟ)暴涨四成。此成果对具身智能产业化有强大推动力。 来源：<a href="https://huggingface.co/papers/2606.28276" target="_blank" rel="noreferrer">三维场景（AI 资讯）</a></p><p><video controls src="'+s+'" title="AI资讯"></video></p><h3 id="_6-meta-发布-brain2qwerty-v2-非侵入式实时句子解码" tabindex="-1">6. Meta 发布 Brain2Qwerty v2：非侵入式实时句子解码 <a class="header-anchor" href="#_6-meta-发布-brain2qwerty-v2-非侵入式实时句子解码" aria-label="Permalink to &quot;6. Meta 发布 Brain2Qwerty v2：非侵入式实时句子解码&quot;">​</a></h3><p>Meta 公布 Brain2Qwerty v2，这是非侵入式脑电信号解码研究的最新里程碑。基于当天发表在《Nature》的 v1，v2 是性能最高的端到端管道，能从原始脑信号实时解码句子。其从字符级性能提升至解码单词和语义，提高整体沟通准确性。该研究有望帮助数百万因脑损伤或疾病无法沟通的人群。 来源：<a href="https://x.com/AIatMeta/status/2071566924803395741" target="_blank" rel="noreferrer">X：AI at Meta (@AIatMeta)</a></p><h3 id="_7-openai-报告-绘制欧洲-ai-劳动力机遇版图" tabindex="-1">7. OpenAI 报告：绘制欧洲 AI 劳动力机遇版图 <a class="header-anchor" href="#_7-openai-报告-绘制欧洲-ai-劳动力机遇版图" aria-label="Permalink to &quot;7. OpenAI 报告：绘制欧洲 AI 劳动力机遇版图&quot;">​</a></h3><p>OpenAI 发布新报告，分析 AI 对欧盟就业的影响，划定哪些职业面临自动化、增长或工作流程变化。 来源：<a href="https://openai.com/index/mapping-ai-jobs-transition-eu" target="_blank" rel="noreferrer">OpenAI：官网动态（RSS · 排除企业/客户案例）</a></p><h3 id="_8-discoformer-一个跨分布同时估计密度与分数的单一-transformer-模型" tabindex="-1">8. DiScoFormer：一个跨分布同时估计密度与分数的单一 Transformer 模型 <a class="header-anchor" href="#_8-discoformer-一个跨分布同时估计密度与分数的单一-transformer-模型" aria-label="Permalink to &quot;8. DiScoFormer：一个跨分布同时估计密度与分数的单一 Transformer 模型&quot;">​</a></h3><p>DiScoFormer（Density and Score Transformer）是一个无需重新训练即可从数据点估计分布密度和分数的单一模型。它利用 Transformer 的交叉注意力机制，在单次前向传播中输出密度和分数，并通过一致性损失实现分布外自适应。在 100 维空间中，DiScoFormer 比最优调参的核密度估计（KDE）降低分数误差约 6.5 倍、密度误差超过 37 倍，且随样本量增加持续提升，而 KDE 内存耗尽。模型基于高斯混合模型训练，可泛化至非高斯分布（如 Laplace、Student-t）及未见过的多模态混合。 来源：<a href="https://huggingface.co/blog/allenai/discoformer" target="_blank" rel="noreferrer">Hugging Face：Blog（RSS）</a></p><h2 id="行业、政策与安全" tabindex="-1">行业、政策与安全 <a class="header-anchor" href="#行业、政策与安全" aria-label="Permalink to &quot;行业、政策与安全&quot;">​</a></h2><h3 id="_1-tidal-平台出台-ai-音乐新政策" tabindex="-1">1. Tidal 平台出台 AI 音乐新政策 <a class="header-anchor" href="#_1-tidal-平台出台-ai-音乐新政策" aria-label="Permalink to &quot;1. Tidal 平台出台 AI 音乐新政策&quot;">​</a></h3><p>Tidal 平台出台 AI 音乐新政策 音乐平台 Tidal 出台 AI 音乐全新政策。下月中旬起不再为 纯 AI 曲目（AI 资讯） 付版税。系统识别的 AI 曲目会被 🔥 强制打上标签。公司强调优先保障(￣^￣)人类创作者利益。但平台并未对生成式音乐全面封杀。 来源：<a href="https://www.theverge.com/tech/959211/tidal-ai-music-policy-demonetizingdetect-label" target="_blank" rel="noreferrer">纯 AI 曲目（AI 资讯）</a></p><h3 id="_2-北京太空算力创新中心揭牌" tabindex="-1">2. 北京太空算力创新中心揭牌 <a class="header-anchor" href="#_2-北京太空算力创新中心揭牌" aria-label="Permalink to &quot;2. 北京太空算力创新中心揭牌&quot;">​</a></h3><p>北京太空算力创新中心揭牌 太空算力创新中心在 海淀中关村 揭牌。这标志前沿算力布局进入 🚀 协同 发展新阶段（AI 资讯）。中心将攻关星载芯片与(✧∀✧)太空大模型。空天地算网协同任督二脉将被彻底打通。太空数据处理将为数字经济注入动力。 来源：<a href="https://www.aibase.com/zh/news/29239" target="_blank" rel="noreferrer">发展新阶段（AI 资讯）</a></p><h3 id="_3-deepseek-创始人决定启动融资" tabindex="-1">3. DeepSeek 创始人决定启动融资 <a class="header-anchor" href="#_3-deepseek-创始人决定启动融资" aria-label="Permalink to &quot;3. DeepSeek 创始人决定启动融资&quot;">​</a></h3><p>DeepSeek 创始人决定启动融资 深度求索创始人受 ClaudeMythos 震撼决定融资。他意识到不储备弹药无法支撑后续的 模型研发（AI 资讯）。公司目前所有部门正在 🔥 疯狂招兵买马。团队正加紧适配国产芯片并(O_O)重写底层。其坚守开源低价与通用人工智能战略未变。 来源：<a href="https://www.qbitai.com/2026/06/439863.html" target="_blank" rel="noreferrer">模型研发（AI 资讯）</a></p><h3 id="_4-国务院印发《教育发展-十五五-规划》-推进人工智能全学段教育" tabindex="-1">4. 国务院印发《教育发展“十五五”规划》，推进人工智能全学段教育 <a class="header-anchor" href="#_4-国务院印发《教育发展-十五五-规划》-推进人工智能全学段教育" aria-label="Permalink to &quot;4. 国务院印发《教育发展“十五五”规划》，推进人工智能全学段教育&quot;">​</a></h3><p>国务院日前印发《教育发展“十五五”规划》，要求推进人工智能全学段教育，提升学生人工智能素养及提出问题、解决问题的能力。规划明确完善科学教育体系，强化科技教育与人文教育协同，加强青少年科学素养、批判性思维和创新能力培养。同时实施学生体质强健计划、心理健康促进行动，加大拔尖创新人才自主培养力度，推动学科交叉融合，扩大优质本科招生规模。目标到 2030 年高质量教育体系基本建成。 来源：<a href="https://www.ithome.com/0/970/097.htm" target="_blank" rel="noreferrer">IT 之家（RSS）</a></p><h3 id="_5-sk-集团会长崔泰源-到-2035-年建设-15gw-ai-数据中心-总投资达-1000-万亿韩元" tabindex="-1">5. SK 集团会长崔泰源：到 2035 年建设 15GW AI 数据中心，总投资达 1000 万亿韩元 <a class="header-anchor" href="#_5-sk-集团会长崔泰源-到-2035-年建设-15gw-ai-数据中心-总投资达-1000-万亿韩元" aria-label="Permalink to &quot;5. SK 集团会长崔泰源：到 2035 年建设 15GW AI 数据中心，总投资达 1000 万亿韩元&quot;">​</a></h3><p>SK 集团会长崔泰源 6 月 29 日宣布，计划到 2035 年建成 15GW AI 数据中心容量，作为韩国国家级基础设施和实体 AI 时代核心底座。项目总投资 1000 万亿韩元（约 4.4 万亿元人民币），未来 10 年保持年均 100 万亿韩元以上国内投资，旨在实现从出口传统商品向智能服务的转变，构建韩国智能市场。此外，SK 海力士将向韩国西南部投资 400 万亿韩元，半导体供应项目总投资达 1100 万亿韩元（约 4.84 万亿元人民币）。 来源：<a href="https://www.ithome.com/0/969/953.htm" target="_blank" rel="noreferrer">IT 之家（RSS）</a></p><h2 id="开源与开发者工具" tabindex="-1">开源与开发者工具 <a class="header-anchor" href="#开源与开发者工具" aria-label="Permalink to &quot;开源与开发者工具&quot;">​</a></h2><h3 id="_1-veracrypt-强大磁盘加密工具" tabindex="-1">1. VeraCrypt: 强大磁盘加密工具 <a class="header-anchor" href="#_1-veracrypt-强大磁盘加密工具" aria-label="Permalink to &quot;1. VeraCrypt: 强大磁盘加密工具&quot;">​</a></h3><p>VeraCrypt: 强大磁盘加密工具 开源项目 VeraCrypt 是 强大加密工具。它基于老牌软件重构解决 数据泄露痛点（AI 资讯）。项目凭极致安全性在社区斩获 🔥 万颗星标。对隐私要求极高的用户(O_O)绝不容错过。 来源：<a href="https://github.com/veracrypt/VeraCrypt" target="_blank" rel="noreferrer">数据泄露痛点（AI 资讯）</a></p><h3 id="_2-tolaria-桌面端知识库管理" tabindex="-1">2. tolaria: 桌面端知识库管理 <a class="header-anchor" href="#_2-tolaria-桌面端知识库管理" aria-label="Permalink to &quot;2. tolaria: 桌面端知识库管理&quot;">​</a></h3><p>tolaria: 桌面端知识库管理 开源项目 tolaria 专注构建 桌面知识库。它完美解决了文档难以高效整理的 管理痛点（AI 资讯）。该仓库已狂揽近一万八千颗 🚀 开发者星标。流畅交互体验让人(✧∀✧)用过就彻底爱不释手。 来源：<a href="https://github.com/refactoringhq/tolaria" target="_blank" rel="noreferrer">管理痛点（AI 资讯）</a></p><h3 id="_3-vulnclaw-自动化安全渗透框架" tabindex="-1">3. VulnClaw: 自动化安全渗透框架 <a class="header-anchor" href="#_3-vulnclaw-自动化安全渗透框架" aria-label="Permalink to &quot;3. VulnClaw: 自动化安全渗透框架&quot;">​</a></h3><p>VulnClaw: 自动化安全渗透框架 开源项目 VulnClaw 打造了 自动渗透框架。AI 智能体解决了人工挖掘效率低下的 测试痛点（AI 资讯）。系统支持自然语言实现 🔥 自动生成安全报告。创新思路迅速吸引了一千多颗(o ﾟ ▽ ﾟ)星标关注。 来源：<a href="https://github.com/Unclecheng-li/VulnClaw" target="_blank" rel="noreferrer">测试痛点（AI 资讯）</a></p><h3 id="_4-free-for-dev-免费开发资源清单" tabindex="-1">4. free-for-dev: 免费开发资源清单 <a class="header-anchor" href="#_4-free-for-dev-免费开发资源清单" aria-label="Permalink to &quot;4. free-for-dev: 免费开发资源清单&quot;">​</a></h3><p>free-for-dev: 免费开发资源清单 项目 freefordev 整理了 免费资源清单。它直击独立开发者寻找白嫖服务的 关键痛点（AI 资讯）。这份宝库目前已经积累超十二万颗 🚀 星标。部署测试还是个人实验(✧∀✧)都能从中找方案。 来源：<a href="https://github.com/ripienaar/free-for-dev" target="_blank" rel="noreferrer">关键痛点（AI 资讯）</a></p><h3 id="_5-logto-现代化身份认证基建" tabindex="-1">5. logto: 现代化身份认证基建 <a class="header-anchor" href="#_5-logto-现代化身份认证基建" aria-label="Permalink to &quot;5. logto: 现代化身份认证基建&quot;">​</a></h3><p>logto: 现代化身份认证基建 开源项目 Logto 提供现代 身份认证基建。它消除开发者构建复杂登录系统的 繁琐痛点（AI 资讯）。项目凭借多租户权限控制收获 🔥 万颗星标。极致开发体验让集成工作变得(o ﾟ ▽ ﾟ)极其简单。 来源：<a href="https://github.com/logto-io/logto" target="_blank" rel="noreferrer">繁琐痛点（AI 资讯）</a></p><h2 id="社媒与观点" tabindex="-1">社媒与观点 <a class="header-anchor" href="#社媒与观点" aria-label="Permalink to &quot;社媒与观点&quot;">​</a></h2><h3 id="_1-独立开发者分享价值开源项目" tabindex="-1">1. 独立开发者分享价值开源项目 <a class="header-anchor" href="#_1-独立开发者分享价值开源项目" aria-label="Permalink to &quot;1. 独立开发者分享价值开源项目&quot;">​</a></h3><p>独立开发者分享价值开源项目 独立开发者分享了多款 极具价值开源项目。有闲置服务器可部署 Dokploy 简化程序流程。Plausible 是绝佳的网站流量统计 🚀 平替工具。搭配短链与(^_−)☆ 监控能打造完美个人基建。神器组合让日常的运维工作变得极其省心。 来源：<a href="https://m.okjike.com/originalPosts/6a41cb3b3d621d78627a6c16" target="_blank" rel="noreferrer">简化程序流程</a></p><p><img src="'+h+'" alt="AI资讯：开发者分享多款值得部署的开源项目列表截图" loading="lazy"></p><h3 id="_2-圈内热议-deepseek-价格上涨" tabindex="-1">2. 圈内热议 DeepSeek 价格上涨 <a class="header-anchor" href="#_2-圈内热议-deepseek-价格上涨" aria-label="Permalink to &quot;2. 圈内热议 DeepSeek 价格上涨&quot;">​</a></h3><p>圈内热议 DeepSeek 价格上涨 圈内热议 DeepSeekAPI 高峰期的 价格上涨动态。更值得关注的是 V4 正式版将于 七月上线。早晚高峰翻倍但整体价格依然 🚀 极具性价比。新版本将带来颠覆性功能与(✧∀✧)性能提升。国产大模型的集体爆发期确实已经悄然来临。 来源：<a href="https://m.okjike.com/originalPosts/6a4297c578e3636d906a2edf" target="_blank" rel="noreferrer">七月上线</a></p><h3 id="_3-qwen-3-6-27b-是本地开发的理想选择" tabindex="-1">3. Qwen 3.6 27B 是本地开发的理想选择 <a class="header-anchor" href="#_3-qwen-3-6-27b-是本地开发的理想选择" aria-label="Permalink to &quot;3. Qwen 3.6 27B 是本地开发的理想选择&quot;">​</a></h3><p>Qwen 3.6 27B 是一款密集参数本地大语言模型，原生支持 256k 上下文。在 Macbook Max M5 上运行 llama.cpp Q8_0 量化版（含多 token 预测）可达 30 tokens/s；用户反馈在 RTX 5090 上 Q6_K 量化可达 50 tokens/s。它可通过单个提示完成创意诗歌、用 pnpm 生成六边形扫雷游戏等任务，作者称其为首个真正具备通用智能的本地模型。另有一个 MoE 变体 35B A3B，但作者推荐 27B 版本。 来源：<a href="https://quesma.com/blog/qwen-36-is-awesome" target="_blank" rel="noreferrer">Hacker News 热门（buzzing.cc 中文翻译）</a></p><h3 id="快讯" tabindex="-1">快讯 <a class="header-anchor" href="#快讯" aria-label="Permalink to &quot;快讯&quot;">​</a></h3><ul><li><strong>博主探讨 Agent 对组织架构影响</strong>：博主探讨 Agent 对组织架构影响 博主深入探讨 Agent 对 组织架构的影响。高管分享的九个非共识洞察引发 圈内共鸣。智能体平台主战场已转向 🔥 人员调配管理。将个体经验沉淀为组织资产才是(O_O)破局核心。按效果收费必将重构未来 AI 领域商业模式。 来源：<a href="https://m.okjike.com/originalPosts/6a4256d673763cc995e92dfd" target="_blank" rel="noreferrer">圈内共鸣</a></li><li><strong>科技圈传出豆包内测社交功能</strong>：科技圈传出豆包内测社交功能 科技圈传出重磅消息称 豆包内测社交功能。应用界面中新增了类似聊天的 全新对话页。用户能添加好友甚至登录阉割版的 🔥 网页端。这意味着 AI 正强势入侵(O_O)人类工作协作流。豆包或将演变为庞大体系内的 AI 消息入口。 来源：<a href="https://m.okjike.com/originalPosts/6a41fab4228d9ca169efb640" target="_blank" rel="noreferrer">全新对话页</a></li><li><strong>分享两个 Vibe Coding 必备的实用 Prompt：第一性原理与对抗式审查</strong>：作者分享 Vibe Coding 中两个关键 Prompt：一是“从第一性原理出发”，强制 AI 跳出类比推理，从基本事实重新推导本质，曾帮作者发现项目抓取海外信源的底层流量路由隐患并彻底重构；二是“对抗式审查”，让 AI 站在恶意用户角度攻防式审查代码，检出 OOM 死循环、未来时间污染等手工难发现的 BUG。两个 Prompt 形成生成与验证闭环，使纯 Vibe Coding 项目最近一周请求量超千万次。 来源：<a href="https://mp.weixin.qq.com/s/umPqTD_-IubbhXIgiS47eQ" target="_blank" rel="noreferrer">公众号：数字生命卡兹克</a></li><li><strong>Anthropic：当 AI 成本超过工程师薪酬</strong>：Anthropic 在算力上的支出达到每位工程师每年 51.5 万美元，是其完全薪资（22.4 万美元）的 2.3 倍。相比之下，顶尖 1%软件公司的算力支出为 8.9 万美元，中位数仅为 1.37 万美元。三个 2029 年情景预测了这一差距的缩小路径。 来源：<a href="https://www.tomtunguz.com/ai-spend-breakeven-2029" target="_blank" rel="noreferrer">Tomer Tunguz 博客（VC 分析）</a></li></ul><h2 id="今日总结与启示" tabindex="-1">今日总结与启示 <a class="header-anchor" href="#今日总结与启示" aria-label="Permalink to &quot;今日总结与启示&quot;">​</a></h2><ul><li><strong>模型与产品更新继续升温。</strong> 美团发布 VitaBench2.0 评测系统 是今天最值得跟进的信号之一，后续要看能力是否能稳定进入真实工作流 🚀。</li><li><strong>前沿研究继续升温。</strong> 智谱 GLM5.2 模型比肩 Claude 是今天最值得跟进的信号之一，后续要看能力是否能稳定进入真实工作流 🧠。</li><li><strong>行业、政策与安全继续升温。</strong> Tidal 平台出台 AI 音乐新政策 是今天最值得跟进的信号之一，后续要看能力是否能稳定进入真实工作流 🔒。</li><li><strong>开源与开发者工具继续升温。</strong> VeraCrypt: 强大磁盘加密工具 是今天最值得跟进的信号之一，后续要看能力是否能稳定进入真实工作流 🛠️。</li><li><strong>社媒与观点继续升温。</strong> 独立开发者分享价值开源项目 是今天最值得跟进的信号之一，后续要看能力是否能稳定进入真实工作流 ( •̀ ω •́ )。</li></ul>',81)])])}const _=a(d,[["render",c]]);export{k as __pageData,_ as default};
